{"term":"zaadcel","lang":"nl","script":"latin","romanization":null,"category":"reproductive_contraceptive","subcategory":"sperm","concept":"sperm","is_novel_concept":false,"register":"clinical","crude":5,"technical":90,"recognition_pct_current":99,"recognition_pct_peak":99,"peak_year":null,"regional":null,"definition":"The male gamete cell produced in the testes; the standard Dutch biological term for spermatozoon.","english_term":"sperm cell","english_translation_quality":"direct","notes":"'Zaad' (seed) preserves an older semantic frame shared with agricultural Dutch; no crude connotation in clinical or educational use."}
{"term":"eicel","lang":"nl","script":"latin","romanization":null,"category":"reproductive_contraceptive","subcategory":"ovum","concept":"ovum","is_novel_concept":true,"register":"clinical","crude":2,"technical":90,"recognition_pct_current":99,"recognition_pct_peak":99,"peak_year":null,"regional":null,"definition":"The female gamete cell produced by the ovary; the egg cell capable of being fertilized by a spermatozoon.","english_term":"egg cell","english_translation_quality":"direct","notes":"Compound of 'ei' (egg) and 'cel' (cell); purely anatomical with zero crude connotation; universal in Dutch biology education."}
{"term":"bevruchting","lang":"nl","script":"latin","romanization":null,"category":"reproductive_contraceptive","subcategory":"fertilization","concept":"fertilization","is_novel_concept":false,"register":"clinical","crude":5,"technical":85,"recognition_pct_current":98,"recognition_pct_peak":98,"peak_year":null,"regional":null,"definition":"Fertilization; the fusion of a sperm cell with an egg cell to form a zygote, initiating embryonic development.","english_term":"fertilization","english_translation_quality":"direct","notes":"Derived from 'bevruchten' (to fertilize/impregnate); shares the same root as the Dutch agricultural term for pollination, giving it a slightly broader semantic range than the English equivalent."}
{"term":"zwangerschap","lang":"nl","script":"latin","romanization":null,"category":"reproductive_contraceptive","subcategory":"pregnancy","concept":"pregnancy","is_novel_concept":true,"register":"clinical","crude":2,"technical":70,"recognition_pct_current":100,"recognition_pct_peak":100,"peak_year":null,"regional":null,"definition":"Pregnancy; the condition of carrying a developing fetus in the uterus from conception to birth.","english_term":"pregnancy","english_translation_quality":"direct","notes":"Universal Dutch word with no crude connotation; 'zwanger' (pregnant) derives from Middle Dutch; the suffix '-schap' forms abstract nouns analogous to English '-hood' or '-ness'."}
{"term":"ongeplande zwangerschap","lang":"nl","script":"latin","romanization":null,"category":"reproductive_contraceptive","subcategory":"unplanned_pregnancy","concept":"unplanned_pregnancy","is_novel_concept":true,"register":"clinical","crude":5,"technical":60,"recognition_pct_current":98,"recognition_pct_peak":98,"peak_year":null,"regional":null,"definition":"Unplanned pregnancy; a pregnancy that was not intended at the time of conception.","english_term":"unplanned pregnancy","english_translation_quality":"direct","notes":"Standard compound phrase in Dutch public health and sex-education contexts; carries social weight in context but is clinically neutral in register; 'onbedoelde zwangerschap' (unintended pregnancy) is an equally common near-synonym."}
{"term":"onveilige seks","lang":"nl","script":"latin","romanization":null,"category":"reproductive_contraceptive","subcategory":"unprotected_sex","concept":"unprotected_sex","is_novel_concept":false,"register":"slang_neutral","crude":15,"technical":35,"recognition_pct_current":95,"recognition_pct_peak":95,"peak_year":null,"regional":null,"definition":"Unsafe sex; sexual intercourse without barrier protection, exposing partners to STI transmission risk or unintended pregnancy.","english_term":"unsafe sex","english_translation_quality":"direct","notes":"Entered mainstream Dutch via 1980s HIV/AIDS public health campaigns; 'onveilig' (unsafe) is the direct antonym of 'veilig' (safe); the phrase is now neutral and educational in register."}
{"term":"veilige seks","lang":"nl","script":"latin","romanization":null,"category":"reproductive_contraceptive","subcategory":"safe_sex","concept":"safe_sex","is_novel_concept":true,"register":"slang_neutral","crude":10,"technical":35,"recognition_pct_current":97,"recognition_pct_peak":97,"peak_year":null,"regional":null,"definition":"Safe sex; sexual practices that reduce the risk of STI transmission and unintended pregnancy, primarily through condom use and communication.","english_term":"safe sex","english_translation_quality":"direct","notes":"Embedded in Dutch vocabulary through SOA AIDS Nederland and GGD campaigns beginning in the 1980s; essentially a loanphrase translated directly from English 'safe sex'; widely accepted without taboo across generations."}
