{"term":"onderdanige","lang":"nl","script":"latin","romanization":null,"category":"kink_paraphilia","subcategory":"bdsm_submissive","concept":"bdsm_submissive","is_novel_concept":false,"register":"slang_neutral","crude":30,"technical":20,"recognition_pct_current":87,"recognition_pct_peak":87,"peak_year":null,"regional":null,"definition":"Submissive person; one who takes the yielding, deferential role in a BDSM or power-exchange dynamic.","english_term":"submissive","english_translation_quality":"direct","notes":"Adjectivized noun from 'onderdanig' (subservient, obedient); used in non-sexual contexts to describe a deferential employee or personality; the sexual meaning is contextual rather than inherent, which keeps its crude score moderate."}
